273	func prepareBrainHistoryProjectionContext(ctx context.Context, outputDir string, now time.Time, progress historyIndexProgress) (*preparedHistoryProjection, error) {
274		// The build itself reads and hashes every non-excluded transcript. The
275		// opening capture therefore needs only the exact metadata membership; the
276		// strong post-capture below binds the build digest without a redundant full
277		// corpus read.
278		identity, manifest, err := captureHistoryProjectionIdentityMode(ctx, outputDir, false)
279		if err != nil {
280			return nil, err
281		}
282		index, source, cache, err := buildBrainHistoryIndexSnapshotContext(ctx, outputDir, now, progress, manifest)
283		if err != nil {
284			return nil, err
285		}
286		identity.SessionContents = cache.contentIdentity
287		receipts := buildProjectionReceiptsFromSnapshot(outputDir, manifest, index, now)
288		after, _, err := captureHistoryProjectionIdentityContext(ctx, outputDir)
289		if err != nil {
290			return nil, err
291		}
292		if !identity.same(after) {
293			return nil, errors.New("memory_source_stale: sessions or short-term overlay changed while preparing history")
294		}
295		// Retain the exact post-scan descriptor/root/tree snapshot for the short
296		// commit revalidation. The content aggregate already equals the immutable
297		// bytes parsed by the build.
298		identity = after
299		indexData, err := json.MarshalIndent(index, "", "  ")
300		if err != nil {
301			return nil, err
302		}
303		indexData = append(indexData, '\n')
304		indexSum := sha256.Sum256(indexData)
305		indexDigest := "sha256:" + hex.EncodeToString(indexSum[:])
306		receiptData, receiptDigest, err := encodeProjectionState(receipts)
307		if err != nil {
308			return nil, err
309		}
310		generationHash := sha256.New()
311		_, _ = generationHash.Write(indexData)
312		_, _ = generationHash.Write(receiptData)
313		generation := hex.EncodeToString(generationHash.Sum(nil))[:40]
314		indexPath := historystore.GenerationArtifactPath(generation, historystore.IndexFileName)
315		receiptPath := historystore.GenerationArtifactPath(generation, projectionStateFileName)
316		stagingDir := filepath.ToSlash(filepath.Join(historystore.StagingDir, generation))
317		stagedIndexPath := filepath.ToSlash(filepath.Join(stagingDir, historystore.IndexFileName))
318		stagedReceiptPath := filepath.ToSlash(filepath.Join(stagingDir, projectionStateFileName))
319		if err := historyProjectionWriteFile(outputDir, stagedIndexPath, indexData, 0o600); err != nil {
320			return nil, fmt.Errorf("stage history index: %w", err)
321		}
322		if err := historyProjectionWriteFile(outputDir, stagedReceiptPath, receiptData, 0o600); err != nil {
323			_ = removeHistoryProjectionDirectory(outputDir, stagingDir)
324			return nil, fmt.Errorf("stage projection receipts: %w", err)
325		}
326		cacheData, _ := encodeHistoryScanCache(cache)
327		source.IndexPath = indexPath
328		source.IndexDigest = indexDigest
329		// Publish the byte/record identities alongside the generation digest. They
330		// are what lets a reader rank straight from the FTS payload table without
331		// loading index.json, what keys the O(1) FTS freshness check, and what
332		// historyIndexCurrent uses to skip an unnecessary rebuild. Omitting them on
333		// the generation-addressed path silently degraded every one of those to the
334		// slow path.
335		source.IndexBytes = int64(len(indexData))
336		source.IndexSHA256 = historystore.IndexBytesFingerprint(indexData)
337		source.RecordsFingerprint = historystore.RecordsFingerprint(index.Records)
338		index.RecordsFingerprint = source.RecordsFingerprint
339		source.ProjectionStatePath = receiptPath
340		source.ProjectionStateDigest = receiptDigest
341		return &preparedHistoryProjection{
342			identity: identity, index: index, source: *source, cacheData: cacheData,
343			indexPath: indexPath, receiptPath: receiptPath, stagingDir: stagingDir, generation: generation,
344		}, nil
345	}
