347	// publishBrainHistoryProjectionLocked is the short commit boundary. Caller
348	// holds the Brain write lock. guard is checked both before validation and at
349	// the final linearization point; the coordinator uses it for cancellation.
350	func publishBrainHistoryProjectionLocked(outputDir string, prepared *preparedHistoryProjection, guard historyProjectionPublishGuard) (*historySourceManifest, error) {
351		if prepared == nil {
352			return nil, errors.New("history projection preparation is missing")
353		}
354		committed := false
355		defer func() {
356			if !committed {
357				_ = discardPreparedHistoryProjection(outputDir, prepared)
358			}
359		}()
360		if guard != nil {
361			if err := guard(); err != nil {
362				return nil, err
363			}
364		}
365		current, _, err := captureHistoryProjectionMetadataIdentity(outputDir)
366		if err != nil {
367			return nil, err
368		}
369		if !current.sameMetadata(prepared.identity) {
370			return nil, errors.New("memory_source_stale: sessions or short-term overlay changed before history commit")
371		}
372		manifest, err := bmanifest.Load(outputDir)
373		if err != nil {
374			return nil, err
375		}
376		if manifest.Sources != nil && manifest.Sources.History != nil {
377			// Only vNext receipts veto the commit: data this binary cannot decode
378			// must not be replaced by a down-converted generation. An UNSAFE
379			// receipt (hardlinked, symlinked, swapped) gets no such protection —
380			// this commit writes a brand-new generation and never reads the old
381			// one, and refusing turned the integrity guard into a permanent
382			// denial of service that no command could clear.
383			_, receiptState, receiptErr := loadProjectionStateChecked(outputDir, manifest.Sources.History)
384			if receiptState == projectionStateUnsupported {
385				if receiptErr != nil {
386					return nil, receiptErr
387				}
388				return nil, fmt.Errorf("active history projection receipts are %s and read-only", receiptState)
389			}
390		}
391		if manifest.Sources == nil {
392			manifest.Sources = &brainSources{}
393		}
394		source := prepared.source
395		manifest.Sources.History = &source
396		if manifest.GeneratedAt.IsZero() {
397			manifest.GeneratedAt = source.GeneratedAt
398		}
399		if guard != nil {
400			if err := guard(); err != nil {
401				return nil, err
402			}
403		}
404		current, _, err = captureHistoryProjectionMetadataIdentity(outputDir)
405		if err != nil {
406			return nil, err
407		}
408		if !current.sameMetadata(prepared.identity) {
409			return nil, errors.New("memory_source_stale: sessions or short-term overlay changed at history commit")
410		}
411		bmanifest.Normalize(manifest)
412		// Normalization may fill default fields on the canonical sessions source.
413		// Publish the fingerprint of the exact normalized source written below so
414		// checked receipt readers do not mistake our own commit for source drift.
415		if manifest.Sources != nil && manifest.Sources.History != nil {
416			manifest.Sources.History.SessionsFingerprint = sessionSourceFingerprint(manifest.Sources.Sessions)
417			source = *manifest.Sources.History
418		}
419		manifest.SchemaVersion = bmanifest.SchemaVersion

